//! The live-DOM geometry Chrome 156 control (`tests/fixtures/live_geometry_chrome156.json`,
//! generated by turbo-dom's `scripts/live-geometry-chrome-control.mjs`): every case is laid
//! out through the live HTML snapshot as turbo-surf takes it (`testing::layout`, surf's UA
//! supplement) and each `[data-cid]` element's border-box bounds are read the way surf's
//! CSSOM-View glue reads them (`metrics::element_geometry`, falling back to
//! `inline::geometry` for a flattened inline), then compared with Chrome's
//! `getBoundingClientRect()`. Covers turbo-surf#31 (blockified positioned inlines,
//! per-element inline failures).
use serde_json::Value;

use super::source_id;
use super::testing::{layout, DOCUMENT};
use crate::cssom_view::{inline, metrics};
use crate::layout::value::Display;
use crate::layout_snapshot::{GeometryKind, Rect};

const FIXTURE: &str = include_str!("../../tests/fixtures/live_geometry_chrome156.json");

/// The flattened-inline error the glue answers with the inline seam instead.
const NO_BORDER_BOX: &str =
    "native live layout requires inline border/cluster provenance for this element";

/// Reads that still fail, by design, with the reason (case, cid, message).
const GAPS: &[(&str, &str, &str)] = &[(
    "unsupported-inline-is-per-element",
    "s",
    "native ordinary inline top/bottom/middle alignment is unsupported",
)];

/// Cases whose compared boxes are laid out with text (the bundled fonts must be there).
const TEXT_CASES: &[&str] = &[
    "table-decorated-collapsed",
    "absolute-span-static-position",
    "sr-only-in-link",
    "unsupported-inline-is-per-element",
];

/// The `<style>` text of a control document (the testing cascade takes the CSS apart
/// from the tree).
fn css_of(html: &str) -> &str {
    html.split_once("<style>")
        .and_then(|(_, rest)| rest.split_once("</style>"))
        .map_or("", |(css, _)| css)
}

fn bounds(
    snapshot: &crate::layout_snapshot::LayoutSnapshot,
    styles: &crate::cssom_view::scroll::SourceStyles,
    id: crate::layout_snapshot::SourceId,
) -> Result<Rect, String> {
    match metrics::element_geometry(snapshot, id) {
        Err(error) if error == NO_BORDER_BOX => inline::geometry(snapshot, styles, id),
        result => result,
    }
    .map(|geometry| geometry.bounds)
}

fn used_display(
    snapshot: &crate::layout_snapshot::LayoutSnapshot,
    id: crate::layout_snapshot::SourceId,
) -> Option<Display> {
    snapshot.source(id)?.fragment_indices.iter().find_map(|&i| {
        let fragment = &snapshot.fragments()[i];
        (fragment.kind == GeometryKind::BorderBox)
            .then_some(fragment.used_box)
            .flatten()
            .map(|used| used.display)
    })
}

fn check_box(
    case: &Value,
    want: &Value,
    got: Result<Rect, String>,
    display: Option<Display>,
    failures: &mut Vec<String>,
) {
    let Some(rect) = answered(case, want, got, failures) else {
        return;
    };
    compare_rect(case, want, rect, failures);
    // A blockified positioned inline lays out as a block box (CSS 2.1 §9.7).
    if want["display"] == "block" && display.is_some_and(|display| display != Display::Block) {
        failures.push(format!(
            "{} used display {display:?}, Chrome block",
            label(case, want)
        ));
    }
}

fn label(case: &Value, want: &Value) -> String {
    format!(
        "{}: {}",
        case["id"].as_str().unwrap(),
        want["cid"].as_str().unwrap()
    )
}

/// The read's rect, or `None` when it failed (a failure unless it is a listed gap with
/// its exact message).
fn answered(
    case: &Value,
    want: &Value,
    got: Result<Rect, String>,
    failures: &mut Vec<String>,
) -> Option<Rect> {
    let gap = GAPS
        .iter()
        .find(|(id, cid, _)| case["id"] == *id && want["cid"] == *cid)
        .map(|(_, _, message)| *message);
    match (got, gap) {
        (Ok(rect), None) => return Some(rect),
        (Err(error), Some(message)) if error == message => {}
        (got, gap) => failures.push(format!("{} read {got:?}, gap {gap:?}", label(case, want))),
    }
    None
}

fn compare_rect(case: &Value, want: &Value, rect: Rect, failures: &mut Vec<String>) {
    let measure = case["measure"][want["cid"].as_str().unwrap()]
        .as_str()
        .unwrap_or("xywh");
    for (key, field, value) in [
        ('x', "x", rect.x),
        ('y', "y", rect.y),
        ('w', "width", rect.width),
        ('h', "height", rect.height),
    ] {
        let chrome = want[field].as_f64().unwrap() as f32;
        if measure.contains(key) && (value - chrome).abs() > 0.01 {
            failures.push(format!(
                "{}.{field} = {value}, Chrome {chrome}",
                label(case, want)
            ));
        }
    }
}

#[test]
fn live_geometry_matches_chrome_156() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    let cases = fixture["cases"].as_array().unwrap();
    let mut failures = Vec::new();
    let mut compared = 0;
    for case in cases {
        let id = case["id"].as_str().unwrap();
        if !cfg!(feature = "bundled-fonts") && TEXT_CASES.contains(&id) {
            continue;
        }
        let html = case["html"].as_str().unwrap();
        let (tree, snapshot, styles) = layout(html, css_of(html), (1280.0, 800.0), Some(1.0));
        for want in case["boxes"].as_array().unwrap() {
            let cid = want["cid"].as_str().unwrap();
            let handle = tree
                .query_selector(&format!("[data-cid=\"{cid}\"]"))
                .unwrap();
            let source = source_id(DOCUMENT, handle);
            let got = bounds(&snapshot, &styles, source);
            check_box(
                case,
                want,
                got,
                used_display(&snapshot, source),
                &mut failures,
            );
            compared += 1;
        }
    }
    assert!(compared > 0);
    assert!(
        failures.is_empty(),
        "{} live reads differ from Chrome 156:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn css_of_reads_the_first_style_element() {
    assert_eq!(css_of("<style>a{}</style><style>b{}</style>"), "a{}");
    assert_eq!(css_of("<p>"), "");
}
